package org.securemail.community.content;

import org.securemail.community.core.*;
import org.securemail.community.access.*;
import java.lang.management.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.KeyPairGenerator;
import java.sql.*;
import java.time.*;
import java.util.*;

/** Bounded real production-handler/SQLite probe. No Tor, native desktop or external API acceptance. */
public final class CommunityLoad500Smoke {
 private CommunityLoad500Smoke(){}
 @FunctionalInterface interface Operation{void run()throws Exception;}
 private static final ThreadMXBean THREADS=ManagementFactory.getThreadMXBean();
 private static long cpu(){return THREADS.isCurrentThreadCpuTimeSupported()?THREADS.getCurrentThreadCpuTime():-1;}
 private static Map<String,Object> measure(int count,Operation op)throws Exception {List<Double> times=new ArrayList<>();long cpu=cpu();for(int i=0;i<count;i++){long start=System.nanoTime();op.run();times.add((System.nanoTime()-start)/1e6);}long endCpu=cpu();Collections.sort(times);Map<String,Object>m=new LinkedHashMap<>();m.put("samples",count);m.put("p50Ms",times.get((int)Math.ceil(count*.50)-1));m.put("p95Ms",times.get((int)Math.ceil(count*.95)-1));m.put("minMs",times.getFirst());m.put("maxMs",times.getLast());m.put("meanMs",times.stream().mapToDouble(Double::doubleValue).average().orElseThrow());m.put("threadCpuTotalMs",cpu<0?null:(endCpu-cpu)/1e6);return m;}
 private static void sql(Connection db,String text,Object...values)throws Exception {try(PreparedStatement p=db.prepareStatement(text)){for(int i=0;i<values.length;i++)p.setObject(i+1,values[i]);p.executeUpdate();}}
 private static void check(boolean condition)throws Exception{if(!condition)throw new IllegalStateException("Load probe assertion failed");}
 @SuppressWarnings("unchecked") private static List<Map<String,Object>> items(Map<String,Object>m,String key){return(List<Map<String,Object>>)m.get(key);}
 private static Map<String,Object> call(ContentService service,String actor,String op,Map<String,Object>data)throws Exception{return service.handle(actor,"content.library."+op,data);}
 private static Map<String,Object> memory(){Map<String,Object>m=new LinkedHashMap<>();MemoryUsage h=ManagementFactory.getMemoryMXBean().getHeapMemoryUsage();m.put("heapUsedBytes",h.getUsed());m.put("heapCommittedBytes",h.getCommitted());m.put("heapMaxBytes",h.getMax());m.put("liveThreads",THREADS.getThreadCount());m.put("peakThreads",THREADS.getPeakThreadCount());try{String status=Files.readString(Path.of("/proc/self/status"));for(String line:status.split("\n"))if(line.startsWith("VmRSS:"))m.put("processRssKiB",Long.parseLong(line.replaceAll("[^0-9]","")));}catch(Exception unsupported){m.put("processRssKiB",null);}return m;}
 private static Map<String,Object> dataset(Path path,int size)throws Exception {
  check(size>=100&&size<=3000);Map<String,Object>report=new LinkedHashMap<>();report.put("materials",size);report.put("privateFraction",.25);report.put("readerRole","no assigned roles");report.put("writerRole","fixture SQL grant; all content changes use production handlers");report.put("memoryBefore",memory());
  try(CommunityStore store=new CommunityStore(path,Clock.systemUTC())){AccessControl access=new AccessControl(store);ContentService content=new ContentService(store,access);String owner=store.ensureIdentity(KeyPairGenerator.getInstance("Ed25519").generateKeyPair().getPublic().getEncoded(),"Автор"),reader=store.ensureIdentity(KeyPairGenerator.getInstance("Ed25519").generateKeyPair().getPublic().getEncoded(),"Читатель");store.tx(db->{String role=UUID.randomUUID().toString();sql(db,"INSERT INTO roles(id,scope,name) VALUES(?,'GLOBAL',?)",role,"Писатель тестовых данных");for(String p:List.of("LIBRARY_CREATE","LIBRARY_EDIT","LIBRARY_PUBLISH","LIBRARY_LINK"))sql(db,"INSERT INTO role_permissions VALUES(?,?)",role,p);sql(db,"INSERT INTO assignments VALUES(?,?)",owner,role);return null;});
   List<String>all=new ArrayList<>(),publicIds=new ArrayList<>(),privateIds=new ArrayList<>();long generationStart=System.nanoTime(),generationCpu=cpu();for(int i=0;i<size;i++){boolean closed=i%4==0;Map<String,Object>d=new LinkedHashMap<>();d.put("title",(closed?"CLOSED-CANARY ":"PUBLIC-CANARY ")+i);d.put("body","Синтетический материал нагрузочной проверки. "+"Данные и разрешения. ".repeat(20));d.put("type",i%2==0?"NOTE":"ARTICLE");if(closed)d.put("policy",Map.of("users",List.of(owner)));Map<String,Object>m=call(content,owner,"create",d);String id=(String)m.get("id");call(content,owner,"publish",Map.of("id",id,"revision",m.get("revision")));all.add(id);(closed?privateIds:publicIds).add(id);}
   int links=Math.min(100,all.size()-1);for(int i=0;i<links;i++){Map<String,Object>e=call(content,owner,"link.propose",Map.of("from",all.get(i),"to",all.get(i+1),"explanation","Связь синтетического набора"));call(content,owner,"link.decide",Map.of("id",e.get("id"),"decision","APPROVE"));}
   report.put("generationWallMs",(System.nanoTime()-generationStart)/1e6);report.put("generationThreadCpuMs",generationCpu<0?null:(cpu()-generationCpu)/1e6);report.put("fixturePublicMaterials",publicIds.size());report.put("fixturePrivateMaterials",privateIds.size());report.put("fixtureApprovedEdges",links);
   String first=publicIds.getFirst(),hidden=privateIds.getFirst();for(int i=0;i<3;i++){call(content,reader,"get",Map.of("id",first));call(content,reader,"list",Map.of("limit",100));call(content,reader,"graph",Map.of("limit",100));}
   Map<String,Object>operations=new LinkedHashMap<>();operations.put("getAllowed",measure(30,()->check(call(content,reader,"get",Map.of("id",first)).get("id").equals(first))));operations.put("getDenied",measure(30,()->{try{call(content,reader,"get",Map.of("id",hidden));throw new IllegalStateException("Closed material leaked");}catch(CommunityException e){check(e.code().equals("NOT_FOUND"));}}));operations.put("firstPage100",measure(20,()->{for(Map<String,Object>m:items(call(content,reader,"list",Map.of("limit",100)),"items"))check(!((String)m.get("title")).contains("CLOSED-CANARY"));}));operations.put("searchHiddenCanary",measure(10,()->check(items(call(content,reader,"list",Map.of("query","CLOSED-CANARY","limit",100)),"items").isEmpty())));operations.put("graphFirst100",measure(20,()->{Map<String,Object>g=call(content,reader,"graph",Map.of("limit",100));Set<String>ids=new HashSet<>();for(Map<String,Object>m:items(g,"nodes")){check(!((String)m.get("title")).contains("CLOSED-CANARY"));ids.add((String)m.get("id"));}for(Map<String,Object>e:items(g,"edges"))check(ids.contains(e.get("from"))&&ids.contains(e.get("to")));}));
   final int[]pageCount={0};operations.put("graphAllPages",measure(3,()->{String cursor="";Set<String>seen=new HashSet<>();int pages=0;do{Map<String,Object>g=call(content,reader,"graph",Map.of("limit",100,"cursor",cursor));Set<String>page=new HashSet<>();for(Map<String,Object>m:items(g,"nodes")){String id=(String)m.get("id");check(!privateIds.contains(id));if(!seen.add(id))check(cursor.startsWith("E:"+id+":"));page.add(id);}for(Map<String,Object>e:items(g,"edges"))check(seen.contains(e.get("from"))&&seen.contains(e.get("to")));cursor=(String)g.get("nextCursor");check(++pages<=size/10+2);}while(!cursor.isEmpty());check(seen.size()==publicIds.size());pageCount[0]=pages;}));report.put("graphPagesPerTraversal",pageCount[0]);report.put("operations",operations);report.put("memoryAfter",memory());report.put("sqliteBytes",Files.size(path));report.put("auditIntegrity",store.verifyAudit());report.put("assertions",Map.of("closedGetDenied",true,"hiddenSearchEmpty",true,"graphOnlyAllowedEndpoints",true,"allPublicNodesPagedWithoutLoss",true));
  }return report;
 }
 public static void main(String[]args)throws Exception {if(args.length!=1)throw new IllegalArgumentException("temporary output directory required");Path directory=Path.of(args[0]).toAbsolutePath();Files.createDirectories(directory);if(THREADS.isThreadCpuTimeSupported()&&!THREADS.isThreadCpuTimeEnabled())THREADS.setThreadCpuTimeEnabled(true);Map<String,Object>out=new LinkedHashMap<>(),machine=new LinkedHashMap<>();for(String p:List.of("os.name","os.version","os.arch","java.version","java.vendor","java.vm.name"))machine.put(p,System.getProperty(p));machine.put("availableProcessors",Runtime.getRuntime().availableProcessors());machine.put("maxHeapBytes",Runtime.getRuntime().maxMemory());machine.put("jvmArguments",ManagementFactory.getRuntimeMXBean().getInputArguments());out.put("schemaVersion",1);out.put("scope","Single-host real SQLite/AccessControl/ContentService benchmark; synthetic data; NOT Tor, native desktop, physical-device or production load acceptance");out.put("machine",machine);List<Map<String,Object>>datasets=new ArrayList<>();for(int n:new int[]{100,1000,3000}){System.err.println("Benchmark dataset: "+n);datasets.add(dataset(directory.resolve("dataset-"+n+".db"),n));}out.put("datasets",datasets);System.out.println(json(out));}
 private static String json(Object value){if(value==null)return"null";if(value instanceof Number||value instanceof Boolean)return value.toString();if(value instanceof String s)return"\""+s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r").replace("\t","\\t")+"\"";if(value instanceof Map<?,?>m){List<String>a=new ArrayList<>();m.forEach((k,v)->a.add(json(k)+":"+json(v)));return"{"+String.join(",",a)+"}";}if(value instanceof Collection<?>c)return"["+String.join(",",c.stream().map(CommunityLoad500Smoke::json).toList())+"]";throw new IllegalArgumentException("JSON type");}
}
